try{const saved=JSON.parse(localStorage.getItem('orbit-sidebar-widths')||'{}');for(const key of Object.keys(sidebarWidths))if(Number.isFinite(saved[key]))sidebarWidths[key]=saved[key];}catch{}
function applySidebarWidths(save=false){
 for(const key of ['projects','conversations']){document.body.classList.toggle(`${key}-collapsed`,sidebarCollapsed[key]);$(`show-${key}`).hidden=!sidebarCollapsed[key];}
 if(!sidebarCollapsed.projects)sidebarWidths.projects=Math.round(Math.max(120,Math.min(340,sidebarWidths.projects,innerWidth-530)));
 if(!sidebarCollapsed.conversations)sidebarWidths.conversations=Math.round(Math.max(210,Math.min(600,sidebarWidths.conversations,innerWidth-(sidebarCollapsed.projects?0:sidebarWidths.projects)-310)));
 for(const [key,panelId,handleId,min,max] of [['projects','project-sidebar','project-resizer',120,340],['conversations','conversation-sidebar','conversation-resizer',210,600]]){
  $(panelId).style.width=`${sidebarWidths[key]}px`;const handle=$(handleId);handle.setAttribute('aria-valuemin',min);handle.setAttribute('aria-valuemax',max);handle.setAttribute('aria-valuenow',sidebarWidths[key]);
 }
 if(save)try{localStorage.setItem('orbit-sidebar-widths',JSON.stringify(sidebarWidths));}catch{}
 requestAnimationFrame(()=>{fitTerminals();updatePreviewBounds();});
}
for(const [id,key] of [['project-resizer','projects'],['conversation-resizer','conversations']]){
 const handle=$(id);let drag=null;
 const end=event=>{if(!drag)return;drag=null;document.body.classList.remove('resizing-sidebar');if(handle.hasPointerCapture(event.pointerId))handle.releasePointerCapture(event.pointerId);applySidebarWidths(true);if(mode==='preview'&&currentURL)run(showBrowser);};
 handle.onpointerdown=event=>{if(event.button!==0)return;event.preventDefault();drag={x:event.clientX,width:sidebarWidths[key]};handle.setPointerCapture(event.pointerId);document.body.classList.add('resizing-sidebar');if(mode==='preview')run(()=>api.hidePreview());};
 handle.onpointermove=event=>{if(!drag)return;sidebarWidths[key]=drag.width+event.clientX-drag.x;applySidebarWidths();};
 handle.onpointerup=end;handle.onpointercancel=end;
 handle.ondblclick=()=>{sidebarWidths[key]=sidebarDefaults[key];applySidebarWidths(true);};
 handle.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home'].includes(event.key))return;event.preventDefault();sidebarWidths[key]=event.key==='Home'?sidebarDefaults[key]:sidebarWidths[key]+(event.key==='ArrowLeft'?-10:10);applySidebarWidths(true);};
}
window.addEventListener('resize',()=>applySidebarWidths());
applySidebarWidths();

let recentQuery='',recentLimit=50,railSections={projects:true,recent:true},railProjectHeight=280;
try{const saved=JSON.parse(localStorage.getItem('luce-rail-sections')||'{}');for(const key of Object.keys(railSections))if(typeof saved[key]==='boolean')railSections[key]=saved[key];}catch{}
try{const saved=Number(localStorage.getItem('luce-rail-split'));if(Number.isFinite(saved)&&saved>0)railProjectHeight=saved;}catch{}
function applyRailSplit(save=false){
 const rail=$('project-sidebar'),projects=$('projects-section'),recent=$('recent-section'),handle=$('rail-section-resizer');
 if(!rail.clientHeight||projectView==='tabs')return;
 const recentMin=100,projectMin=70,footerHeight=$('add-project').offsetHeight+14,available=rail.clientHeight-footerHeight-handle.offsetHeight-recentMin;
 const max=Math.max(projectMin,available),height=Math.round(Math.max(projectMin,Math.min(max,railProjectHeight)));
 railProjectHeight=height;projects.style.height=`${height}px`;projects.style.flex=railSections.recent?'0 1 auto':'1 1 0';
 projects.classList.toggle('section-folded',!railSections.projects);recent.classList.toggle('section-folded',!railSections.recent);
 handle.hidden=!railSections.projects||!railSections.recent;
 handle.setAttribute('aria-valuemin',projectMin);handle.setAttribute('aria-valuemax',max);handle.setAttribute('aria-valuenow',height);
 if(save)try{localStorage.setItem('luce-rail-split',String(railProjectHeight));}catch{}
}
new ResizeObserver(()=>applyRailSplit()).observe($('project-sidebar'));
function applyRailSections(){
 $('projects').hidden=!railSections.projects;$('recent-content').hidden=!railSections.recent;
 for(const [key,id,label] of [['projects','toggle-project-list','PROJECTS'],['recent','toggle-recent','RECENT CONVERSATIONS']]){$(id).textContent=`${railSections[key]?'▾':'▸'} ${label}`;$(id).setAttribute('aria-expanded',railSections[key]);}
 applyRailSplit();
}
for(const [key,id] of [['projects','toggle-project-list'],['recent','toggle-recent']])$(id).onclick=()=>{railSections[key]=!railSections[key];try{localStorage.setItem('luce-rail-sections',JSON.stringify(railSections));}catch{}applyRailSections();};
{
 const handle=$('rail-section-resizer');let drag=null;
 const finish=event=>{if(!drag)return;drag=null;document.body.classList.remove('resizing-rail-sections');if(handle.hasPointerCapture(event.pointerId))handle.releasePointerCapture(event.pointerId);applyRailSplit(true);};
 handle.onpointerdown=event=>{if(event.button!==0)return;event.preventDefault();drag={y:event.clientY,height:railProjectHeight};handle.setPointerCapture(event.pointerId);document.body.classList.add('resizing-rail-sections');};
 handle.onpointermove=event=>{if(!drag)return;railProjectHeight=drag.height+event.clientY-drag.y;applyRailSplit();};
 handle.onpointerup=finish;handle.onpointercancel=finish;
 handle.ondblclick=()=>{railProjectHeight=280;applyRailSplit(true);};
 handle.onkeydown=event=>{if(!['ArrowUp','ArrowDown','Home'].includes(event.key))return;event.preventDefault();railProjectHeight=event.key==='Home'?280:railProjectHeight+(event.key==='ArrowUp'?-10:10);applyRailSplit(true);};
 window.addEventListener('resize',()=>applyRailSplit());
}
function recentTitle(h){const p=state.projects.find(p=>p.id===h.assignedProjectId)||state.projects.find(p=>p.directory===h.directory);return historyTitle(h,p);}
function recentGroup(date){const day=new Date(date);day.setHours(0,0,0,0);const today=new Date();today.setHours(0,0,0,0);const yesterday=new Date(today);yesterday.setDate(yesterday.getDate()-1);return day.getTime()===today.getTime()?'Today':day.getTime()===yesterday.getTime()?'Yesterday':new Date(date).toLocaleDateString(undefined,{month:'short',day:'numeric',year:day.getFullYear()!==today.getFullYear()?'numeric':undefined});}
async function organizeRecent(h,open=false,targetProjectId=null){let p=targetProjectId?state.projects.find(row=>row.id===targetProjectId):state.projects.find(row=>row.id===h.assignedProjectId)||state.projects.find(row=>!row.conversationGroup&&row.directory===h.directory);if(targetProjectId){await api.assignConversation(conversationIdentity(h),targetProjectId);p=state.projects.find(row=>row.id===targetProjectId);}else if(!p)p=await api.addProject(h.directory);if(!p)return;await api.selectProject(p.id);state=await api.getState();mode='terminal';expanded=false;setFocused(false);render();if(open)await createTerminal(h.provider,h);}
async function newProjectForRecent(h){const defaultName=h.directory.split('/').filter(Boolean).pop()||h.directory,name=await nameDialog('Add to a new project',defaultName);if(!name)return;const p=await run(()=>api.createConversationProject(conversationIdentity(h),name));if(!p)return;state=await api.getState();await api.selectProject(p.id);state=await api.getState();mode='terminal';render();}
function recentMenu(row,h){const items=[{label:'Open conversation',icon:h.provider,action:()=>organizeRecent(h,true)},{label:'Rename in Luce',icon:'history',action:()=>renameHistory(h)},{label:'Add to existing project',icon:'folder',disabled:!state.projects.length,action:()=>popup(row,state.projects.map(p=>({label:p.name,hint:p.id===h.assignedProjectId?'Current':'',action:()=>organizeRecent(h,false,p.id)})))},{label:'Add to a new project…',icon:'folder',action:()=>newProjectForRecent(h)}];if(!state.projects.some(p=>!p.conversationGroup&&p.directory===h.directory))items.push({label:'Add folder to projects',icon:'folder',action:()=>addProject(h.directory)});popup(row,items);}
function renderRecents(){
 if(draggedConversationKey)return;
 const list=$('recent-list');list.replaceChildren();
 const items=state.history.filter(h=>`${recentTitle(h)} ${h.directory} ${providerName(h.provider)} ${accountName(h.accountId)}`.toLowerCase().includes(recentQuery));let group='';
 for(const h of items.slice(0,recentLimit)){
  const next=recentGroup(h.updatedAt);if(next!==group){group=next;const label=document.createElement('div');label.className='recent-date';label.textContent=group;list.append(label);}
  const row=document.createElement('button');row.className='recent-row';row.dataset.conversationId=h.id;row.title=`${recentTitle(h)}\n${h.directory}\n${providerName(h.provider)} · ${new Date(h.updatedAt).toLocaleString()}`;row.draggable=true;row.ondragstart=event=>{const identity=conversationIdentity(h);draggedConversationKey=conversationDragKey(identity);event.dataTransfer.setData('application/x-luce-conversation',JSON.stringify(identity));event.dataTransfer.effectAllowed='move';};row.ondragend=()=>{draggedConversationKey=null;clearProjectDrop();renderProjects();renderRecents();};
  const folder=h.directory.split('/').filter(Boolean).pop()||h.directory;
  row.innerHTML=`<span class="recent-title">${escape(recentTitle(h))}</span><span class="recent-meta"><span class="recent-folder-line"><span>${escape(folder)}</span><span class="recent-size" title="Saved conversation transcript on disk; excludes project files">${formatDiskSize(h.diskBytes)}</span></span><span>${escape(h.provider==='codex'?accountName(h.accountId):providerName(h.provider))} · ${escape(relativeTime(h.updatedAt))}</span></span>`;
  row.onclick=()=>run(()=>organizeRecent(h,true));row.oncontextmenu=event=>{event.preventDefault();recentMenu(row,h);};list.append(row);
 }
 if(!items.length){const empty=document.createElement('div');empty.className='empty-list';empty.textContent=state.historyLoading?'Looking for saved conversations…':recentQuery?'No matching conversations.':'Saved Codex and Claude conversations from all folders appear here.';list.append(empty);}
 if(items.length>recentLimit){const more=document.createElement('button');more.className='recent-more';more.textContent='Show more';more.onclick=()=>{recentLimit+=50;renderRecents();};list.append(more);}
}
$('recent-search').oninput=event=>{recentQuery=event.target.value.toLowerCase();recentLimit=50;renderRecents();};
$('refresh-recents').onclick=()=>run(async()=>{await api.refreshHistory();state=await api.getState();renderRecents();});
applyRailSections();


function accountName(id='default'){return state.accounts?.find(a=>a.id===id)?.name||'Work';}
function usageFor(s){return s.provider==='codex'?state.accounts?.find(a=>a.id===s.accountId)?.usage:s.usage;}
function usageSummary(s){const u=usageFor(s);if(!u?.windows?.length)return 'Usage —';return `${u.windows[0].label} · ${Math.round(100-u.windows[0].usedPercent)}% left${u.stale?' · stale':''}`;}
function usageHTML(usage){if(!usage?.windows?.length)return '<p class="account-note">Usage unavailable. Codex can be refreshed below; Claude reports usage after a response.</p>';return usage.windows.map(w=>`<div class="quota-window"><div><strong>${escape(w.label)}</strong><span>${Math.round(100-w.usedPercent)}% left</span></div><progress max="100" value="${Math.max(0,100-w.usedPercent)}" aria-label="${escape(w.label)} remaining usage"></progress><small>${w.resetsAt?`Resets ${escape(new Date(w.resetsAt*1000).toLocaleString())}`:'Reset time unavailable'}</small></div>`).join('')+`<p class="account-note">Updated ${escape(relativeTime(usage.updatedAt))}${usage.stale?' · stale, refresh to retry':''}</p>`;}
function compactUsageHTML(usage,provider){
 if(!usage?.windows?.length)return `<div class="usage-unavailable">Usage unavailable. ${provider==='codex'?'Refresh to try again.':'Claude reports usage after a response.'}</div>`;
 const windows=usage.windows.map(w=>{const remaining=Math.max(0,Math.min(100,100-w.usedPercent));return `<div class="compact-quota"><div class="compact-quota-heading"><strong>${escape(w.label)}</strong><span>${Math.round(remaining)}% left</span></div><progress max="100" value="${remaining}" aria-label="${escape(w.label)} remaining usage"></progress><small>${w.resetsAt?`Resets ${escape(new Date(w.resetsAt*1000).toLocaleString())}`:'Reset time unavailable'}</small></div>`;}).join('');
 return `${windows}<div class="usage-updated">Updated ${escape(relativeTime(usage.updatedAt))}${usage.stale?' <span class="usage-stale">· stale</span>':''}</div>`;
}
async function usageDialog(s){
 const provider=s.provider==='codex'?'Codex':'Claude Code',name=s.provider==='codex'?accountName(s.accountId):provider;
 const content=document.createElement('div');content.className='usage-dialog';content.innerHTML=`<div class="usage-account"><strong>${escape(name)}</strong><span>${escape(provider)} account limits · shared across its conversations</span></div><div class="usage-quotas">${compactUsageHTML(usageFor(s),s.provider)}</div>`;
 if(s.provider==='codex'){const refresh=document.createElement('button');refresh.type='button';refresh.className='usage-refresh';refresh.textContent='Refresh usage';refresh.onclick=()=>run(async()=>{refresh.disabled=true;try{await api.refreshAccounts();state=await api.getState();}finally{closeModal();await usageDialog(s);}});content.append(refresh);}
 await openModal('Usage limits',content,'');
}
