async function showAccounts(){const content=document.createElement('div');content.className='accounts-content';content.innerHTML='<p>Keep separate Codex accounts signed in. Choose an account per project or conversation.</p><div id="account-list"></div><div class="add-account-form"><label for="account-name">Add a Codex account</label><div><input id="account-name" placeholder="Personal" maxlength="60"><button id="add-account-button" type="button" class="primary">Add & sign in</button></div></div><p class="account-note">Work uses your existing Codex login. Added accounts have separate settings and histories. Switching a conversation copies its saved history to the selected account.</p><button id="refresh-accounts-button" type="button">Refresh accounts and usage</button>';
 content.insertAdjacentHTML('afterbegin',githubPanel.tabs('codex'));await openModal('Accounts',content,'');githubPanel.bindTabs(content);renderAccounts();$('account-name').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('add-account-button').click();}};$('modal-form').onsubmit=e=>e.preventDefault();
 $('add-account-button').onclick=()=>run(async()=>{const button=$('add-account-button');button.disabled=true;try{const a=await api.addAccount($('account-name').value);$('account-name').value='';await api.loginAccount(a.id);}finally{button.disabled=false;state=await api.getState();renderAccounts();}});
 $('refresh-accounts-button').onclick=()=>run(async()=>{const b=$('refresh-accounts-button');b.disabled=true;try{await api.refreshAccounts();}finally{b.disabled=false;}});
}
function renderAccounts(){const list=$('account-list');if(!list)return;const focusedInput=document.activeElement?.closest('.account-card')?.dataset.accountId;const caret=document.activeElement?.selectionStart;const edits=new Map([...list.querySelectorAll('.account-card')].map(row=>[row.dataset.accountId,row.querySelector('input').value]));list.replaceChildren();for(const a of state.accounts||[]){const row=document.createElement('section');row.className='account-card';row.dataset.accountId=a.id;row.innerHTML=`<div class="account-card-heading"><input aria-label="Account name ${escape(a.name)}" maxlength="60" value="${escape(edits.get(a.id)||a.name)}"><button type="button" class="rename-account">Rename</button></div><p class="account-identity">${escape(a.email|| (a.managed?'Separate Codex login':'Existing Codex environment'))}${a.plan?` · ${escape(a.plan)}`:''}</p><p class="account-note">${escape(a.status==='signed-in'?'Signed in':a.status==='signing-in'?'Waiting for browser sign-in':a.status==='checking'?'Checking account…':a.message||'Sign in to continue')}</p>${usageHTML(a.usage)}<div class="account-card-actions">${a.managed?`<button type="button" class="signin-account">${a.status==='signed-in'?'Sign in again':'Sign in'}</button>${a.status==='signing-in'?'<button type="button" class="cancel-signin">Cancel sign-in</button>':''}<button type="button" class="remove-account">Remove from Luce</button>`:''}</div>`;
 row.querySelector('.rename-account').onclick=()=>run(()=>api.renameAccount(a.id,row.querySelector('input').value));row.querySelector('.signin-account')?.addEventListener('click',()=>run(()=>api.loginAccount(a.id)));row.querySelector('.cancel-signin')?.addEventListener('click',()=>run(()=>api.cancelAccountLogin(a.id)));row.querySelector('.remove-account')?.addEventListener('click',()=>run(()=>api.removeAccount(a.id)));list.append(row);if(focusedInput===a.id){row.querySelector('input').focus();row.querySelector('input').setSelectionRange(caret,caret);}}}
function accountMenu(anchor,s){popup(anchor,[...state.accounts.map(a=>({label:a.name,hint:a.id===s.accountId?'Current':a.status==='signed-in'?(a.usage?.windows?.length?`${Math.round(100-a.usage.windows[0].usedPercent)}% left`:'Signed in'):'Sign in first',disabled:a.id===s.accountId||a.status!=='signed-in',action:async()=>{let fresh=false;if(!s.conversationId){const choice=await chooseAccountStart();if(!choice)return;fresh=choice==='fresh';if(!fresh&&!await chooseConversation(s))return;}toast(fresh?'Starting a new conversation…':'Saving conversation and switching account…');const next=await api.switchAccount(s.id,a.id,{fresh});if(!next)return;state=await api.getState();const ids=slots.get(s.projectId)||[];slots.set(s.projectId,ids.map(id=>id===s.id?next.id:id));focusSession(next.id);toast(fresh?`New conversation with ${a.name}.`:next.continuation?'Started a text continuation. Click Paste context when Codex is ready, then press Enter.':`Conversation resumed with ${a.name}.`);}})),{divider:true},{label:'Manage accounts',action:showAccounts}]);}
