async function chooseConversation(s){await api.refreshHistory();state=await api.getState();const p=state.projects.find(p=>p.id===s.projectId),content=document.createElement('div');content.innerHTML='<p>Select the saved conversation that belongs to this terminal. Luce cannot reliably identify a new conversation from its terminal output.</p><div class="discover-list"></div>';const list=content.querySelector('div');const rows=state.history.filter(h=>h.provider==='codex'&&h.accountId===s.accountId&&h.directory===s.workingDirectory&&(h.assignedProjectId?h.assignedProjectId===p.id:!p.conversationGroup));if(!rows.length)list.innerHTML='<p>Send a message in Codex and wait for it to save, then try again.</p>';await openModal('Choose saved conversation',content,'');return new Promise(resolve=>{let done=false;const finish=result=>{if(done)return;done=true;$('modal').onclose=null;closeModal();resolve(result);};$('modal').onclose=()=>finish(null);for(const h of rows){const b=document.createElement('button');b.type='button';b.className='discover-item';b.innerHTML=`<div><strong>${escape(historyTitle(h,p))}</strong><small>${escape(relativeTime(h.updatedAt))} · ${escape(accountName(h.accountId))}</small></div>`;b.onclick=()=>run(async()=>{await api.linkConversation(s.id,h.id);finish(h);});list.append(b);}});}

function setupPaneDrop(pane,index){
 pane.dataset.slot=index;
 pane.ondragover=e=>{if(!e.dataTransfer.types.includes('application/x-luce-terminal')&&!(e.dataTransfer.types.includes('Files')||e.dataTransfer.types.includes('application/x-luce-file')))return;e.preventDefault();e.dataTransfer.dropEffect='move';pane.classList.add('drop-target');};
 pane.ondragleave=e=>{if(!pane.contains(e.relatedTarget))pane.classList.remove('drop-target');};
 pane.ondrop=e=>{e.preventDefault();pane.classList.remove('drop-target');if(e.dataTransfer.types.includes('application/x-luce-file')){run(async()=>{const file=JSON.parse(e.dataTransfer.getData('application/x-luce-file'));const path=await api.resolveProjectFile(file.projectId,file.relative);pastePath(pane.dataset.sessionId,path);});return;}if(e.dataTransfer.files.length){run(()=>pasteFiles(pane.dataset.sessionId,[...e.dataTransfer.files]));return;}const id=e.dataTransfer.getData('application/x-luce-terminal'),p=project(),ids=[...(slots.get(p.id)||[])],from=ids.indexOf(id);if(from<0||from===index||focused)return;[ids[from],ids[index]]=[ids[index]||null,id];slots.set(p.id,ids);renderWorkspace();views.get(id)?.terminal.focus();};
}
function diskSizeHTML(s){const h=state.history.find(h=>h.id===s.conversationId&&h.provider===s.provider&&(s.provider!=='codex'||h.accountId===s.accountId));if(!Number.isFinite(h?.diskBytes))return '<span class="pane-disk" title="Size available once this terminal is linked to its saved conversation">Size —</span>';const label=formatDiskSize(h.diskBytes);return `<span class="pane-disk" title="Saved conversation transcript on disk; excludes project files">${label}</span>`;}
async function chooseAccountStart(){const content=document.createElement('div');content.innerHTML='<p>Start fresh with this account, or continue a saved conversation?</p><button type="button" class="primary" data-choice="fresh">Start new conversation</button> <button type="button" data-choice="saved">Continue saved conversation</button>';await openModal('Switch account',content,'');return new Promise(resolve=>{let done=false;const finish=value=>{if(done)return;done=true;$('modal').onclose=null;closeModal();resolve(value);};$('modal').onclose=()=>finish(null);content.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>finish(b.dataset.choice));});}

function formatDiskSize(bytes){if(!Number.isFinite(bytes))return "—";return bytes>=1048576?`${(bytes/1048576).toFixed(1)} MB`:bytes>=1024?`${Math.ceil(bytes/1024)} KB`:`${bytes} B`;}

function projectTerminalBadge(id){const working=state.terminals.filter(s=>s.projectId===id&&s.status==='running'&&s.working).length;const count=state.terminals.filter(s=>s.projectId===id&&s.status==='running').length;const finished=state.terminals.filter(s=>s.projectId===id&&s.completionPending).length;const attention=state.terminals.some(s=>s.projectId===id&&s.completionPending&&s.completionReason==='attention');return (working?`<span class="project-working-count project-status-dot" role="img" title="${working} agent${working===1?'':'s'} actively working" aria-label="${working} agent${working===1?'':'s'} actively working">${working>1?`<small>${working}</small>`:''}</span>`:'')+(finished?`<span class="project-completion-dot project-status-dot" role="img" title="${attention?'An agent needs your attention':`${finished} agent response${finished===1?'':'s'} finished`} — open project to review" aria-label="${attention?'An agent needs your attention':`${finished} agent response${finished===1?'':'s'} finished`}">${finished>1?`<small>${finished}</small>`:''}</span>`:'')+(count?`<span class="project-terminal-count" title="${count} running terminal${count===1?'':'s'}" aria-label="${count} running terminal${count===1?'':'s'}">${count}</span>`:'');}

