async function pasteFiles(id,files,clipboard=false){
 const view=views.get(id);if(!view)throw Error('Drop files onto an open terminal.');const paths=[];
 for(const file of files){let location=api.filePath(file);const temporary=/\/TemporaryItems\/NSIRD_screencaptureui_[^/]+\//.test(location);if((clipboard||temporary||!location)&&file.type.startsWith('image/')){if(file.size>25*1024*1024)throw Error('Image attachments must be 25 MB or smaller.');let bytes;try{bytes=new Uint8Array(await file.arrayBuffer());}catch{throw Error('macOS blocked this temporary screenshot. Save it to Desktop, then drop the saved file here.');}location=await api.saveAttachment(id,bytes);}if(!location)throw Error('No local file path was available. Save the file, then drop it here.');if(/[\x00-\x1f\x7f]/.test(location))throw Error('This filename contains terminal control characters. Rename it before dropping.');paths.push(location);}
 view.terminal.paste(paths.map(location=>"'"+location.replace(/'/g,"'\\''")+"'").join(' '));view.terminal.focus();
}

function setProjectView(value){projectView=value==='tabs'?'tabs':'sidebar';localStorage.setItem('luce-project-view',projectView);renderProjects();applyRailSplit();requestAnimationFrame(()=>{fitTerminalGrid();fitTerminals();updatePreviewBounds();});}

document.addEventListener('keydown',event=>{if(!event.metaKey||event.altKey||event.ctrlKey||event.shiftKey||! /^[1-9]$/.test(event.key))return;event.preventDefault();const n=Number(event.key),target=state.projects[n===9?state.projects.length-1:n-1];if(target)run(()=>selectProject(target.id));});

function columnSpanSet(projectId){if(!columnSpans.has(projectId)){let saved=[];try{saved=JSON.parse(localStorage.getItem(`luce-column-fill:${projectId}`)||'[]');}catch{}columnSpans.set(projectId,new Set(Array.isArray(saved)?saved.filter(id=>typeof id==='string').slice(0,4):[]));}return columnSpans.get(projectId);}
function toggleColumnFill(session){if(state.workspaceRestoring)return;const p=state.projects.find(p=>p.id===session.projectId);if(!p||p.id!==state.selectedProjectId)return;const set=columnSpanSet(p.id);if(set.has(session.id))set.delete(session.id);else if(columnFill(slots.get(p.id)||[],session.id,p.layout))set.add(session.id);else return;localStorage.setItem(`luce-column-fill:${p.id}`,JSON.stringify([...set]));renderWorkspace();views.get(session.id)?.terminal.focus();}

function hydrateArrangement(){
 let saved={};try{saved=JSON.parse(localStorage.getItem('luce-terminal-arrangement')||'{}');}catch{}
 const resolve=(id,projectId)=>state.terminals.find(s=>s.projectId===projectId&&(s.id===id||s.restoredFromId===id))?.id||null;
 for(const p of state.projects){const row=saved.projects?.[p.id];if(Array.isArray(row?.slots))slots.set(p.id,row.slots.slice(0,4).map(id=>resolve(id,p.id)));const active=resolve(row?.active,p.id);if(active)activeProjects.set(p.id,active);const focusedId=resolve(row?.focused,p.id)||(saved.focused?.projectId===p.id?resolve(saved.focused.id,p.id):null);if(focusedId)focusedProjects.set(p.id,focusedId);const set=columnSpanSet(p.id);columnSpans.set(p.id,new Set([...set].map(id=>resolve(id,p.id)).filter(Boolean)));try{localStorage.setItem(`luce-column-fill:${p.id}`,JSON.stringify([...columnSpans.get(p.id)]));}catch{}}
 activeId=activeProjects.get(state.selectedProjectId)||null;focused=!!activeId&&focusedProjects.get(state.selectedProjectId)===activeId;
 if(saved.preview?.projectId===state.selectedProjectId&&typeof saved.preview.url==='string'&&/^https?:\/\//.test(saved.preview.url)){currentURL=saved.preview.url;previewSessionId=resolve(saved.preview.sessionId,state.selectedProjectId);mode='preview';expanded=!!saved.preview.expanded;restoreBrowserPending=true;$('preview-url').value=currentURL;}
}
function persistArrangement(){
 if(!arrangementHydrated||state.workspaceRestoring)return;const projects={};for(const p of state.projects)projects[p.id]={slots:slots.get(p.id)||[],active:p.id===state.selectedProjectId?activeId:activeProjects.get(p.id)||null,focused:focusedProjects.get(p.id)||null};
 try{localStorage.setItem('luce-terminal-arrangement',JSON.stringify({projects,focused:focused?{projectId:state.selectedProjectId,id:activeId}:null,preview:mode==='preview'?{projectId:state.selectedProjectId,url:currentURL,sessionId:previewSessionId,expanded}:null}));}catch{}
}

function pastePath(id,path){const view=views.get(id);if(!view)throw Error('Drop files onto an open terminal.');if(/[\x00-\x1f\x7f]/.test(path))throw Error('This filename contains terminal control characters.');view.terminal.paste("'"+path.replace(/'/g,"'\\''")+"'");view.terminal.focus();}

function setFocused(value,projectId=state.selectedProjectId){focused=!!value&&!!activeId;if(focused)focusedProjects.set(projectId,activeId);else focusedProjects.delete(projectId);}
let restoreNoticeKey='';
function renderRestoreNotices(){const failures=(state.restoreFailures||[]).filter(f=>f.projectId===state.selectedProjectId),key=JSON.stringify(failures);if(key===restoreNoticeKey)return;restoreNoticeKey=key;const box=$('restore-notices');box.replaceChildren();box.hidden=!failures.length;for(const failure of failures){const row=document.createElement('div');row.className='restore-notice';const heading=document.createElement('strong');heading.textContent=`${failure.title} couldn't reopen`;const detail=document.createElement('p');detail.textContent=failure.message;const retry=document.createElement('button');retry.textContent='Retry';retry.onclick=()=>run(async()=>{retry.disabled=true;try{await api.retryWorkspace();}finally{retry.disabled=false;}});const dismiss=document.createElement('button');dismiss.textContent='Dismiss';dismiss.title='Stop trying to reopen this terminal';dismiss.onclick=()=>run(()=>api.dismissWorkspace(failure.id));row.append(heading,detail,retry,dismiss);box.append(row);}}
